        correct: 0,
        r: "በዕድገት ሂደት ውስጥ የሰው ልጅ ራስ ወዳድነት የሚያስተካክለውን ብርሃን የሚጠይቅ ደረጃ ላይ ደርሷል, ስለዚህ መሸሸጊያው ተወግዷል."
